"use client";

import { useEffect, useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { DataGridProvider, DataGridRoot, DataGridHeader, DataGridBody, defineColumns } from "@/registry/default/components/data-grid/data-grid";
import { DataGridContextMenu } from "@/registry/default/components/data-grid-context-menu/data-grid-context-menu";
import { useDataGridComments, type CellComment, type CommentAuthor, type CommentSaveCtx } from "@/registry/default/components/data-grid-comments/data-grid-comments";
import { createCommentsServer } from "./data-grid-comments-demo-server";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 85, flex: 1 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 100, flex: 2 },
  { id: "role", header: "Role", accessorKey: "role", type: "text", width: 65, flex: 1 },
  { id: "score", header: "Logins (30 days)", accessorKey: "score", type: "number", width: 55, flex: 1 },
] as const);

const ME: CommentAuthor = { id: "ada", name: "Ada", color: "oklch(0.7 0.17 60)" };
const PEER: CommentAuthor = { id: "grace", name: "Grace", color: "oklch(0.55 0.2 260)" };
const LATENCY_MS = 400;

const SEED_TIME = Date.UTC(2026, 0, 5, 10, 0);

function peerComment(id: string, rowId: string, columnId: string, text: string, version = 1, now = SEED_TIME): CellComment {
  return { id, rowId, columnId, text, author: PEER, createdAt: now, updatedAt: now, version, writeId: `peer-${id}-${version}`, resolved: false };
}

/** A second user and an in-memory server stand in for the app's own backend and channel. */
function useSimulatedBackend() {
  const rows = useMemo(() => generateDemoRows(24), []);
  const server = useMemo(() => {
    const created = createCommentsServer({ mode: "cas" });
    created.seed([peerComment("seed-1", rows[1]?.id ?? "r1", "name", "Is this the right spelling?"), peerComment("seed-2", rows[4]?.id ?? "r4", "score", "Please double-check this login count.")]);
    return created;
  }, [rows]);
  return { rows, server };
}

export default function DataGridCommentsServerDemo() {
  const { rows, server } = useSimulatedBackend();
  const [offline, setOffline] = useState(false);
  const [log, setLog] = useState("Open a cell and press Shift+F2, or right-click and choose Comments…");
  const seed = useMemo(() => Array.from(server.records.values()), [server]);
  const [timers] = useState(() => new Set<ReturnType<typeof setTimeout>>());
  const [peerCount, setPeerCount] = useState(0);

  useEffect(() => () => timers.forEach(clearTimeout), [timers]);

  const later = (fn: () => void): void => {
    const timer = setTimeout(() => {
      timers.delete(timer);
      fn();
    }, LATENCY_MS);
    timers.add(timer);
  };

  const comments = useDataGridComments({
    currentUser: ME,
    defaultComments: seed,
    onCommentSave: async ({ change }: CommentSaveCtx) => {
      await new Promise((resolve) => setTimeout(resolve, LATENCY_MS));
      if (offline) throw new Error("offline");
      return server.apply(change).ack;
    },
    onCommentRejected: ({ reason, message }) => setLog(`Write reverted: ${reason}${message ? ` (${message})` : ""}`),
    onLocalChange: (change) => setLog(`Saved ${change.kind === "upsert" ? "comment" : "delete"} at version ${change.kind === "upsert" ? change.comment.version : change.version}`),
  });

  const peerAdds = (): void => {
    const target = rows[(peerCount * 3 + 2) % rows.length];
    if (!target) return;
    const record = peerComment(`peer-${peerCount}`, target.id, columns[peerCount % columns.length]?.id ?? "name", "Peer comment: please review.", 1, Date.now());
    const result = server.apply({ kind: "upsert", comment: record, baseVersion: 0 });
    setPeerCount((n) => n + 1);
    later(() => {
      if (result.broadcast) comments.applyRemote([result.broadcast]);
    });
  };

  const forceConflict = (): void => {
    const first = Array.from(server.records.values()).find((c) => c.author?.id === ME.id) ?? server.records.get("seed-1");
    if (!first) return;
    const edited = { ...first, text: `${first.text} (peer edit)`, version: first.version + 1, updatedAt: Date.now(), writeId: `peer-edit-${first.version + 1}` };
    server.apply({ kind: "upsert", comment: edited, baseVersion: first.version });
    setLog("Grace edited a comment on the server. Edit that comment now to see the conflict.");
  };

  return (
    <div className="flex w-full flex-col gap-3">
      <div className="flex flex-wrap items-center gap-2">
        <Button variant="outline" size="sm" onClick={peerAdds}>
          Grace adds a comment
        </Button>
        <Button variant="outline" size="sm" onClick={forceConflict}>
          Grace edits a comment (force a conflict)
        </Button>
        <Button variant={offline ? "default" : "outline"} size="sm" aria-pressed={offline} onClick={() => setOffline((v) => !v)}>
          {offline ? "Offline: saves fail" : "Go offline"}
        </Button>
      </div>
      <p role="status" className="text-sm text-muted-foreground">
        {log}
      </p>
      <div className="flex h-[400px] flex-col overflow-hidden rounded-md border border-border">
        <DataGridProvider defaultData={rows} columns={columns} getRowId={(row) => row.id} plugins={[comments.plugin]}>
          <DataGridContextMenu className="flex min-h-0 flex-1 flex-col" getCellMenuItems={comments.getCommentMenuItems}>
            <DataGridRoot className="min-h-0 flex-1 rounded-none border-none">
              <DataGridHeader />
              <DataGridBody />
            </DataGridRoot>
          </DataGridContextMenu>
        </DataGridProvider>
      </div>
    </div>
  );
}

import type { CellComment, CommentChange, CommentSaveAck } from "@/registry/default/components/data-grid-comments/data-grid-comments";

/** How the in-memory server treats a write: `cas` accepts it only when its `baseVersion` equals the stored version, `lww` accepts every write. */
export type CommentsServerMode = "cas" | "lww";

export type CommentsServerOptions = {
  mode?: CommentsServerMode;
  /** Stamp `updatedAt` and return the authoritative record on every accepted write. */
  stamp?: boolean;
  now?: () => number;
};

export type CommentsServerResult = {
  ack: CommentSaveAck | undefined;
  /** The change to broadcast to the other clients, when the write was accepted. */
  broadcast?: CommentChange;
};

/** A compare-and-swap comments store for the demo and the model test. It plays the app's own backend. */
export type CommentsServer = {
  readonly records: ReadonlyMap<string, CellComment>;
  apply(change: CommentChange): CommentsServerResult;
  list(rowIds: readonly string[]): CellComment[];
  seed(records: readonly CellComment[]): void;
};

export function createCommentsServer(options: CommentsServerOptions = {}): CommentsServer {
  const mode = options.mode ?? "cas";
  const now = options.now ?? (() => Date.now());
  const records = new Map<string, CellComment>();
  const deleted = new Map<string, number>();

  const storedVersion = (id: string): number => records.get(id)?.version ?? deleted.get(id) ?? 0;

  return {
    records,
    seed(list) {
      for (const record of list) records.set(record.id, record);
    },
    list(rowIds) {
      const wanted = new Set(rowIds);
      return [...records.values()].filter((record) => wanted.has(record.rowId));
    },
    apply(change) {
      const id = change.kind === "upsert" ? change.comment.id : change.id;
      const current = records.get(id);
      const base = change.baseVersion ?? 0;
      if (change.kind === "upsert" && current && change.comment.writeId !== undefined && current.writeId === change.comment.writeId) {
        return { ack: options.stamp ? { comment: current } : undefined };
      }
      if (mode === "cas" && base !== storedVersion(id)) {
        return { ack: { rejected: { reason: "stale", current: current ?? null } } };
      }
      if (change.kind === "delete") {
        const version = mode === "cas" ? change.version : Math.max(change.version, storedVersion(id) + 1);
        records.delete(id);
        deleted.set(id, version);
        const differs = version !== change.version;
        return { ack: options.stamp || differs ? { comment: null } : undefined, broadcast: { ...change, version } };
      }
      const version = mode === "cas" ? change.comment.version : Math.max(change.comment.version, storedVersion(id) + 1);
      const stamped: CellComment = { ...change.comment, version, updatedAt: options.stamp ? now() : change.comment.updatedAt };
      records.set(id, stamped);
      deleted.delete(id);
      const differs = version !== change.comment.version;
      return { ack: options.stamp || differs ? { comment: stamped } : undefined, broadcast: { kind: "upsert", comment: stamped } };
    },
  };
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const FIRST_NAMES = [
  "Ava", "Liam", "Mia", "Noah", "Priya", "Mateo", "Yuki", "Omar", "Elena", "Kofi",
  "Sofia", "Ravi", "Hannah", "Diego", "Amara", "Lukas", "Nadia", "Tomas", "Ingrid", "Jamal",
  "Chloe", "Arjun", "Fatima", "Ethan", "Leila", "Marco", "Zara", "Felix", "Mei", "Jonas",
  "Aisha", "Pavel", "Clara", "Hugo", "Nina", "Samir", "Alma", "Oskar", "Lucia", "Dev",
] as const;
const LAST_NAMES = [
  "Becker", "Okafor", "Nguyen", "Lindqvist", "Alvarez", "Tanaka", "Haddad", "Moreau", "Kowalski", "Joshi",
  "Rossi", "Teixeira", "Novak", "Fischer", "Mensah", "Larsen", "Castillo", "Ivanov", "Yamamoto", "Duarte",
  "Brennan", "Hoffmann", "Santos", "Kaya", "Weber", "Adeyemi", "Petrov", "Lopez", "Chen", "Murphy",
  "Bianchi", "Hartmann", "Ito", "Reyes", "Sorensen", "Qureshi", "Ferraz", "Dubois", "Park", "Svensson",
] as const;

/**
 * Generates `count` deterministic rows of a fictional user directory (seed 42, stable across renders).
 * `score` is the number of logins in the last 30 days.
 */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  const emailUses = new Map<string, number>();
  for (let i = 0; i < count; i++) {
    const first = FIRST_NAMES[Math.floor(next() * FIRST_NAMES.length)]!; // fixed non-empty literal arrays
    const last = LAST_NAMES[Math.floor(next() * LAST_NAMES.length)]!;
    const handle = `${first}.${last}`.toLowerCase();
    const uses = (emailUses.get(handle) ?? 0) + 1;
    emailUses.set(handle, uses);
    rows.push({
      id: `row-${i}`,
      name: `${first} ${last}`,
      email: `${handle}${uses > 1 ? uses : ""}@example.com`,
      age: Math.floor(next() * 44) + 21,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
